CREATE TABLE professores (id_prof INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, materia TEXT NOT NULL);
CREATE TABLE turma (id_turma INTEGER PRIMARY KEY AUTOINCREMENT, nome_turma TEXT NOT NULL, tipo TEXT NOT NULL CHECK(tipo IN ('Programação','Design')));
CREATE TABLE alunos (id_aluno INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, id_turma INTEGER NOT NULL, FOREIGN KEY (id_turma) REFERENCES turma(id_turma));
CREATE TABLE notas (id_nota INTEGER PRIMARY KEY AUTOINCREMENT, id_aluno INTEGER NOT NULL, materia TEXT NOT NULL, nota REAL NOT NULL, FOREIGN KEY (id_aluno) REFERENCES alunos(id_aluno));




